CultureManagement = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=CultureManagement]");
		api.addToMetaCache([
			{
        "Name": "Core",
        "Types": [
            [meta[Core/Culture]]
        ]
    }
		]);

		var linkedCultureIds = (await api.get("ContentManagement/AppCulture?$filter=AppId eq " + app.Id)).value.map(r => r.CultureId);

        var cultures = (await api.get("ContentManagement/Culture")).value;
        cultures.forEach(p => p.Has = (linkedCultureIds.indexOf(p.Id) !== -1));	

		var grid = new GridWidget(container, { data: cultures, pageSize: 20 });
		grid.pageable = false;
		grid.columns = [
            {field: "Has", title: " ", template: "<input type='checkbox' #= (Has == true) ? checked ='checked' : '' # class='chkbx k-checkbox'/>", width: 40},
			{ field: "Id", title: '[resource_displayname[Id]]', width: 70 },
			{ field: "Name", title: '[resource_displayname[Name]]' }
		];
		grid.groupable = false;
        grid.editable = false;
        grid.pageable = false;
        grid.filterable = false;
        grid.sortable = false;
        grid.dataBound = function() {
            $("input[type=checkbox]", grid.gridElement).off("click").on("click", async function(e) {
                e.preventDefault();
                var dataItem = grid.dataItem($(e.target).closest("tr"));
                dataItem.set("Has", this.checked);
				if(this.checked) {
					await api.post("ContentManagement/AppCulture", { AppId : app.Id, CultureId: dataItem.Id }).then(() => notification.success("[resource_displayname[added]]"))
						.catch((err) => error(err));
				} else {
					await api.destroy("ContentManagement/AppCulture(AppId=" + app.Id + ",CultureId='" + dataItem.Id + "')").then(() => notification.success("[resource_displayname[deleted]]"))
						.catch((err) => error(err));
				}
            });
        };
        await grid.init();
	},

}
